#!/usr/bin/env bash
# Provision an isolated, sandboxed Hermes Telegram gateway.
#
#   sudo bash /home/dnguyen/Projects/hermes-telebot-setup/hermes-telebot-provision.sh
#
# Idempotent: safe to re-run. Every action is skipped when already applied.
# Writes an acceptance-test transcript to:
#   /home/dnguyen/Projects/hermes-telebot-setup/hermes-telebot-provision.log
#
# Design notes (differ from hermes-gateway-isolation-spec.md, deliberately):
#  * The unit is GENERATED by `hermes gateway install --system --run-as-user`,
#    not hand-written. Hermes rewrites that unit on version changes
#    (systemd_unit_is_current), which would erase inline hardening.
#  * Sandboxing therefore lives in a systemd DROP-IN, which survives
#    regeneration.
#  * ProtectHome=read-only + ReadWritePaths re-mount keeps $HERMES_HOME
#    writable while the rest of /home stays read-only.
#  * /home/dnguyen is made INACCESSIBLE (not merely read-only): the operator
#    asked for no project access, so there are no ACL grants at all.

set -Eeuo pipefail

# ---------------------------------------------------------------- parameters
SVC="hermes-telebot"
SRC_USER="dnguyen"
SRC_HERMES="/home/dnguyen/.hermes"
SRC_ENV="$SRC_HERMES/.env"
SVC_HOME="/home/$SVC"
SVC_HERMES="$SVC_HOME/.hermes"
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
LOG="$SCRIPT_DIR/hermes-telebot-provision.log"
SECRETS="$SCRIPT_DIR/hermes-telebot.secrets"   # optional
ROLLBACK="$SCRIPT_DIR/hermes-telebot-rollback.md"
SVC_UID="$(id -u "$SRC_USER")"

PASS=0
FAIL=0

# ------------------------------------------------------------------- helpers
mkdir -p "$(dirname "$LOG")"
: > "$LOG"
chown "$SRC_USER:$SRC_USER" "$LOG" 2>/dev/null || true

say()  { printf '\n== %s ==\n' "$*"               | tee -a "$LOG"; }
log()  { printf '   %s\n' "$*"                    | tee -a "$LOG"; }
warn() { printf '   ! %s\n' "$*"                  | tee -a "$LOG"; }
die()  { printf '\nFATAL: %s\n' "$*"              | tee -a "$LOG" >&2; exit 1; }

check() {  # check <label> <command...>
  local label="$1"; shift
  if "$@" >/dev/null 2>&1; then
    printf '   PASS  %s\n' "$label" | tee -a "$LOG"; PASS=$((PASS+1))
  else
    printf '   FAIL  %s\n' "$label" | tee -a "$LOG"; FAIL=$((FAIL+1))
  fi
}

as_svc() { runuser -u "$SVC" -- env HOME="$SVC_HOME" HERMES_HOME="$SVC_HERMES" \
             PATH="$SVC_HOME/.local/bin:/usr/local/bin:/usr/bin:/bin" "$@"; }

svc_hermes() { as_svc "$SVC_HERMES/hermes-agent/.hermes/bin/hermes" "$@"; }

# --------------------------------------------------------------- pre-flight
say "pre-flight"
[ "$(id -u)" -eq 0 ] || die "must run as root: sudo bash $0"
[ -r "$SRC_ENV" ]    || die "missing $SRC_ENV"

TOKEN="$(grep -m1 '^TELEGRAM_BOT_TOKEN=' "$SRC_ENV" | cut -d= -f2- || true)"
[ -n "$TOKEN" ] || die "TELEGRAM_BOT_TOKEN not found in $SRC_ENV"

RAW_ALLOWED="$(grep -m1 '^TELEGRAM_ALLOWED_USERS=' "$SRC_ENV" | cut -d= -f2- || true)"
ALLOWED="$(printf '%s' "$RAW_ALLOWED" | tr ',' '\n' | tr -d ' ' \
             | grep -E '^[0-9]+$' | paste -sd, - || true)"
[ -n "$ALLOWED" ] || die "no numeric IDs in TELEGRAM_ALLOWED_USERS ($RAW_ALLOWED)"
if [ "$ALLOWED" != "$RAW_ALLOWED" ]; then
  warn "TELEGRAM_ALLOWED_USERS had non-numeric entries; keeping only: $ALLOWED"
  warn "  (source value was: $RAW_ALLOWED)"
fi

HOME_CHANNEL="$(grep -m1 '^TELEGRAM_HOME_CHANNEL=' "$SRC_ENV" | cut -d= -f2- || true)"
[ -n "$HOME_CHANNEL" ] || HOME_CHANNEL="$(printf '%s' "$ALLOWED" | cut -d, -f1)"

AVAIL_KB="$(df --output=avail /home | tail -1 | tr -d ' ')"
[ "$AVAIL_KB" -gt 3145728 ] || die "need >3 GB free on /home (have $((AVAIL_KB/1024)) MB)"

log "target user      : $SVC"
log "target HERMES_HOME: $SVC_HERMES"
log "allowed users    : $ALLOWED"
log "home channel     : $HOME_CHANNEL"
log "bot token        : reusing the existing token (old gateway will be stopped)"

# --------------------------------------------------------- 1. create the user
say "1/8 user $SVC"
if id "$SVC" >/dev/null 2>&1; then
  log "already exists"
else
  useradd --create-home --shell /bin/bash --comment "Hermes gateway (sandboxed)" "$SVC"
  log "created"
fi
passwd --lock "$SVC" >/dev/null 2>&1 || true
chmod 0700 "$SVC_HOME"
install -d -o "$SVC" -g "$SVC" -m 0700 "$SVC_HERMES" "$SVC_HOME/projects"

GRP_LIST="$(id -nG "$SVC")"
log "groups: $GRP_LIST"
if printf '%s' "$GRP_LIST" | tr ' ' '\n' | grep -Eqx 'sudo|wheel|docker|adm|lpadmin|ollama|systemd-journal'; then
  die "$SVC has a privileged group; aborting before any further change"
fi

# ------------------------------------------------------- 2. install Hermes
say "2/8 hermes install"
if [ -x "$SVC_HERMES/hermes-agent/.hermes/bin/hermes" ]; then
  log "already installed"
else
  log "running upstream installer as $SVC (several minutes; downloads python/node/chromium)"
  runuser -u "$SVC" -- env HOME="$SVC_HOME" HERMES_HOME="$SVC_HERMES" \
    bash -lc 'curl -fsSL https://hermes-agent.nousresearch.com/install.sh \
              | bash -s -- --non-interactive --skip-computer-use' 2>&1 | tee -a "$LOG"
fi
chown -R "$SVC:$SVC" "$SVC_HOME"
[ -x "$SVC_HERMES/hermes-agent/.hermes/bin/hermes" ] || die "install did not produce a hermes launcher"
svc_hermes --version 2>&1 | tee -a "$LOG"

# ------------------------------------------------------------- 3. minimal env
say "3/8 minimal .env"
ENV_FILE="$SVC_HERMES/.env"
TMP_ENV="$(mktemp)"; chmod 600 "$TMP_ENV"
{
  printf '# Hermes gateway (%s) — minimal credential set, do not add unrelated keys\n' "$SVC"
  printf 'TELEGRAM_BOT_TOKEN=%s\n' "$TOKEN"
  printf 'TELEGRAM_ALLOWED_USERS=%s\n' "$ALLOWED"
  printf 'TELEGRAM_HOME_CHANNEL=%s\n' "$HOME_CHANNEL"
} > "$TMP_ENV"

# Optional LiteLLM virtual key + endpoint supplied by the operator.
# Parsed, never sourced: a malformed secrets file must not abort provisioning.
if [ -r "$SECRETS" ]; then
  log "reading $SECRETS"
  secret() { grep -m1 "^$1=" "$SECRETS" 2>/dev/null | cut -d= -f2- | tr -d '"'"'" || true; }
  LITELLM_API_KEY="$(secret LITELLM_API_KEY)"
  LITELLM_BASE_URL="$(secret LITELLM_BASE_URL)"
  LITELLM_MODEL="$(secret LITELLM_MODEL)"
  [ -n "${LITELLM_API_KEY:-}"  ] && printf 'LITELLM_API_KEY=%s\n'  "$LITELLM_API_KEY"  >> "$TMP_ENV" || true
  [ -n "${LITELLM_BASE_URL:-}" ] && printf 'LITELLM_BASE_URL=%s\n' "$LITELLM_BASE_URL" >> "$TMP_ENV" || true
  [ -n "${LITELLM_MODEL:-}"    ] && printf 'LITELLM_MODEL=%s\n'    "$LITELLM_MODEL"    >> "$TMP_ENV" || true
else
  LITELLM_API_KEY=""; LITELLM_BASE_URL=""; LITELLM_MODEL=""
  warn "no $SECRETS — model provider will be left unconfigured"
fi

# Preserve any extra keys an operator already added to the live .env.
if [ -r "$ENV_FILE" ]; then
  while IFS= read -r line; do
    case "$line" in ''|\#*) continue;; esac
    k="${line%%=*}"
    grep -q "^${k}=" "$TMP_ENV" || printf '%s\n' "$line" >> "$TMP_ENV"
  done < "$ENV_FILE"
  if grep -q '^TELEGRAM_BOT_TOKEN=' "$ENV_FILE"; then
    old="$(grep -m1 '^TELEGRAM_BOT_TOKEN=' "$ENV_FILE" | cut -d= -f2-)"
    if [ "$old" != "$TOKEN" ]; then
      warn "live .env has a DIFFERENT bot token — keeping the live one"
      sed -i "s|^TELEGRAM_BOT_TOKEN=.*|TELEGRAM_BOT_TOKEN=$old|" "$TMP_ENV"
    fi
  fi
fi

install -o "$SVC" -g "$SVC" -m 0600 "$TMP_ENV" "$ENV_FILE"
rm -f "$TMP_ENV"
log "wrote $ENV_FILE (0600 $SVC:$SVC)"

# -------------------------------------------------------- 4. model + config
say "4/8 model configuration"
if [ -n "${LITELLM_BASE_URL:-}" ] && [ -n "${LITELLM_MODEL:-}" ]; then
  svc_hermes config set --force providers.litellm.base_url "$LITELLM_BASE_URL" 2>&1 | tee -a "$LOG" || true
  svc_hermes config set --force providers.litellm.key_env LITELLM_API_KEY     2>&1 | tee -a "$LOG" || true
  svc_hermes config set model.provider litellm                                2>&1 | tee -a "$LOG" || true
  svc_hermes config set model.default  "$LITELLM_MODEL"                       2>&1 | tee -a "$LOG" || true
else
  warn "LITELLM_BASE_URL / LITELLM_MODEL not set — skipping (see the tail of this log)"
fi
# Nothing may run unbounded in an unattended gateway.
svc_hermes config set approvals.mode smart 2>&1 | tee -a "$LOG" || true
chown -R "$SVC:$SVC" "$SVC_HERMES"

# --------------------------------------------------------- 5. system unit
say "5/8 system unit"
# Hermes names the unit after the profile: plain "hermes-gateway" only when
# HERMES_HOME is the caller's own ~/.hermes. Installed from root for a foreign
# home it appends a hash (hermes-gateway-<hash>). Discover it; never assume.
unit_path_for_svc() {
  local f
  for f in /etc/systemd/system/hermes-gateway*.service; do
    [ -e "$f" ] || continue
    grep -qF "HERMES_HOME=$SVC_HERMES" "$f" 2>/dev/null && { printf '%s\n' "$f"; return 0; }
  done
  return 1
}

UNIT="$(unit_path_for_svc || true)"
if [ -z "$UNIT" ]; then
  HERMES_HOME="$SVC_HERMES" "$SVC_HERMES/hermes-agent/.hermes/bin/hermes" \
    gateway install --system --run-as-user "$SVC" --no-start-now --start-on-login --force \
    2>&1 | tee -a "$LOG"
  UNIT="$(unit_path_for_svc || true)"
else
  log "unit already present: $UNIT"
fi
[ -n "$UNIT" ] || die "no system unit referencing $SVC_HERMES was generated"

# Root sees /home/hermes-telebot/.hermes as a "foreign" home, so Hermes hashes
# the unit name (hermes-gateway-<hash>). The same install run as that user
# computes the bare name, so `hermes gateway status` there would look for a
# unit that does not exist. Rename to the canonical name once, so every account
# and plain `systemctl status hermes-gateway` agree.
BARE=/etc/systemd/system/hermes-gateway.service
if [ "$UNIT" != "$BARE" ]; then
  if [ -e "$BARE" ] && ! grep -qF "HERMES_HOME=$SVC_HERMES" "$BARE"; then
    die "$BARE exists but belongs to a different HERMES_HOME; resolve by hand"
  fi
  systemctl disable "$(basename "$UNIT" .service)" >/dev/null 2>&1 || true
  mv "$UNIT" "$BARE"
  log "renamed $(basename "$UNIT") -> hermes-gateway.service"
  UNIT="$BARE"
  systemctl daemon-reload
  systemctl enable hermes-gateway >/dev/null 2>&1 || true
fi

UNIT_NAME="$(basename "$UNIT" .service)"
log "unit name: $UNIT_NAME"
chown -R "$SVC:$SVC" "$SVC_HERMES"

say "5b/8 sandbox drop-in"
DROPIN_DIR="$UNIT.d"
install -d -m 0755 "$DROPIN_DIR"
cat > "$DROPIN_DIR/10-isolation.conf" <<EOF
# Managed by hermes-telebot-provision.sh — do NOT move these into the unit
# itself: \`hermes gateway install\` regenerates the unit on version changes and
# would drop them.
[Service]
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=read-only
ReadWritePaths=$SVC_HOME
InaccessiblePaths=/home/dnguyen
PrivateTmp=yes
PrivateDevices=yes
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectKernelLogs=yes
ProtectControlGroups=yes
ProtectClock=yes
ProtectHostname=yes
ProtectProc=invisible
RestrictSUIDSGID=yes
RestrictRealtime=yes
CapabilityBoundingSet=
AmbientCapabilities=
LockPersonality=yes
SystemCallArchitectures=native
UMask=0077
MemoryMax=8G
TasksMax=512
EOF
chmod 0644 "$DROPIN_DIR/10-isolation.conf"
log "wrote $DROPIN_DIR/10-isolation.conf"
systemctl daemon-reload

# --------------------------------------------------------------- 6. flip
say "6/8 token flip (Telegram delivers each update to ONE consumer)"
if runuser -u "$SRC_USER" -- env XDG_RUNTIME_DIR="/run/user/$SVC_UID" \
     DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$SVC_UID/bus" \
     systemctl --user is-enabled hermes-gateway >/dev/null 2>&1; then
  # Disable first: an enabled-but-stopped unit would come back at next boot and
  # fight the new gateway for the same getUpdates offset.
  runuser -u "$SRC_USER" -- env XDG_RUNTIME_DIR="/run/user/$SVC_UID" \
    DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$SVC_UID/bus" \
    systemctl --user disable --now hermes-gateway 2>&1 | tee -a "$LOG" || true
  log "stopped and disabled the old user unit"
else
  log "old user unit already disabled"
fi

loginctl enable-linger "$SVC" >/dev/null 2>&1 || true

systemctl enable "$UNIT_NAME" >/dev/null 2>&1 || true
systemctl start "$UNIT_NAME" || true
for _ in $(seq 1 30); do
  if [ "$(systemctl is-active "$UNIT_NAME")" = active ]; then break; fi
  sleep 2
done

if [ "$(systemctl is-active "$UNIT_NAME")" != active ]; then
  warn "gateway did not come up with the full sandbox — retrying without ProtectHome"
  journalctl -u "$UNIT_NAME" -n 40 --no-pager 2>&1 | tee -a "$LOG" || true
  sed -i '/^ProtectHome=/d' "$DROPIN_DIR/10-isolation.conf"
  systemctl daemon-reload
  systemctl restart "$UNIT_NAME" || true
  for _ in $(seq 1 30); do
    if [ "$(systemctl is-active "$UNIT_NAME")" = active ]; then break; fi
    sleep 2
  done
  warn "re-run this script after inspecting the journal above"
fi
log "state: $(systemctl is-active "$UNIT_NAME")"

# --------------------------------------------------------- 7. acceptance
say "7/8 acceptance tests"
check "no privileged groups on $SVC" \
  bash -c "! id -nG $SVC | tr ' ' '\n' | grep -Eqx 'sudo|wheel|docker|adm|lpadmin|ollama'"
check "not a sudoer" \
  bash -c "runuser -u $SVC -- sudo -n -l 2>&1 | grep -q 'not in the sudoers'"
check "cannot read operator ssh key" \
  bash -c "! runuser -u $SVC -- cat /home/dnguyen/.ssh/id_ed25519"
check "cannot read operator .env" \
  bash -c "! runuser -u $SVC -- cat /home/dnguyen/.hermes/.env"
check "cannot read operator home at all" \
  bash -c "! runuser -u $SVC -- ls /home/dnguyen"
check "cannot use docker socket" \
  bash -c "! runuser -u $SVC -- docker ps"
check "cannot write to operator home" \
  bash -c "! runuser -u $SVC -- touch /home/dnguyen/pwn_test"
check "home is 0700" \
  bash -c "[ \"\$(stat -c %a $SVC_HOME)\" = 700 ]"
check "HERMES_HOME is 0700" \
  bash -c "[ \"\$(stat -c %a $SVC_HERMES)\" = 700 ]"
check ".env is 0600" \
  bash -c "[ \"\$(stat -c %a $SVC_HERMES/.env)\" = 600 ]"
check "NoNewPrivileges enforced" \
  bash -c "[ \"\$(systemctl show $UNIT_NAME -p NoNewPrivileges --value)\" = yes ]"
check "ProtectSystem=strict" \
  bash -c "[ \"\$(systemctl show $UNIT_NAME -p ProtectSystem --value)\" = strict ]"
PID="$(systemctl show -p MainPID --value "$UNIT_NAME")"
if [ -n "$PID" ] && [ "$PID" != 0 ] && [ -r "/proc/$PID/status" ]; then
  check "CapEff is empty" \
    bash -c "grep -q '^CapEff:\s*0000000000000000' /proc/$PID/status"
  check "NoNewPrivs=1 on the live process" \
    bash -c "grep -q '^NoNewPrivs:\s*1' /proc/$PID/status"
  check "runs as $SVC" \
    bash -c "[ \"\$(stat -c %U /proc/$PID)\" = $SVC ]"
else
  warn "MainPID unavailable — skipping /proc checks"
fi
check "unit is enabled" \
  bash -c "systemctl is-enabled $UNIT_NAME | grep -q enabled"

# The tests above run OUTSIDE the sandbox. These run inside the live service's
# mount namespace, so they prove what the gateway process itself can reach.
PID="$(systemctl show -p MainPID --value "$UNIT_NAME")"
if [ -n "$PID" ] && [ "$PID" != 0 ] && [ -r "/proc/$PID/status" ]; then
  check "live process cannot see /home/dnguyen (InaccessiblePaths)" \
    bash -c "! nsenter -t $PID -m -- ls /home/dnguyen"
  check "live process can still read its own .env" \
    bash -c "nsenter -t $PID -m -- test -r $SVC_HERMES/.env"
  check "live process cannot write outside its home" \
    bash -c "! nsenter -t $PID -m -- touch /etc/hermes_pwn_test"
else
  warn "MainPID unavailable — skipping namespace checks"
fi

say "journal tail"
journalctl -u "$UNIT_NAME" -n 30 --no-pager 2>&1 | tee -a "$LOG" || true

say "gateway self-report"
svc_hermes gateway status 2>&1 | tee -a "$LOG" || true

# ------------------------------------------------------------ 8. rollback doc
say "8/8 rollback notes"
cat > "$ROLLBACK" <<EOF
# Rollback — hermes-telebot gateway ($(date -Is))

The isolated gateway reuses the original bot token, so the old user unit was
stopped and DISABLED (\`systemctl --user disable --now hermes-gateway\`).

## Go back to the old gateway

    sudo systemctl disable --now $UNIT_NAME
    systemctl --user enable --now hermes-gateway
    hermes gateway status

## Full teardown

    sudo systemctl disable --now $UNIT_NAME
    sudo rm -f $UNIT
    sudo rm -rf $UNIT.d
    sudo systemctl daemon-reload
    loginctl disable-linger hermes-telebot
    sudo userdel -r hermes-telebot

No ACL grants were made, so there is nothing to revoke. If that changes, remove
them before \`userdel\` — UIDs get reused:

    sudo setfacl -R -x u:hermes-telebot <DIR>
    sudo find <DIR> -type d -exec setfacl -x d:u:hermes-telebot {} +

## Re-running

    sudo bash /home/dnguyen/Projects/hermes-telebot-setup/hermes-telebot-provision.sh
EOF
chown "$SRC_USER:$SRC_USER" "$ROLLBACK"

printf '\n================ %d passed, %d failed =================\n' "$PASS" "$FAIL" | tee -a "$LOG"
[ "$FAIL" -eq 0 ] || exit 1
